"""Boot key and LSA secrets from offline SYSTEM and SECURITY registry hives.

Vista+ LSA encryption only (the AES ``Policy\\PolEKList`` scheme). The pre-Vista
RC4 ``PolSecretEncryptionKey`` layout (Windows XP / 2003) is a different era and is
out of scope here; those hives raise :class:`UnsupportedHive`.
"""
import hashlib
import struct

from Crypto.Cipher import AES
from Registry import Registry

# The scrambled boot key is stored across four LSA subkey class names; this permutation
# unscrambles the 16 assembled bytes into the real boot key (syskey).
_BOOTKEY_PERM = [0x8, 0x5, 0x4, 0x2, 0xb, 0x9, 0xd, 0x3,
                 0x0, 0x6, 0x1, 0xc, 0xe, 0xa, 0xf, 0x7]
_BOOTKEY_SUBKEYS = ('JD', 'Skew1', 'GBG', 'Data')


class UnsupportedHive(Exception):
    """Raised when a hive uses a layout this module does not implement."""


def _current_control_set(reg):
    return 'ControlSet%03d' % reg.open('Select').value('Current').value()


def get_bootkey(system_path):
    """The 16-byte boot key (syskey) from a SYSTEM hive."""
    with open(system_path, 'rb') as handle:
        reg = Registry.Registry(handle)
        lsa = reg.open(_current_control_set(reg) + '\\Control\\Lsa')
        scrambled = b''.join(
            bytes.fromhex(lsa.subkey(name)._nkrecord.classname())  # pylint: disable=protected-access
            for name in _BOOTKEY_SUBKEYS)
    return bytes(scrambled[_BOOTKEY_PERM[i]] for i in range(16))


def _aes_unwrap(key, data):
    """AES-CBC with a zero IV, one block at a time (the LSA/PolEKList unwrap)."""
    out = b''
    for off in range(0, len(data), 16):
        block = data[off:off + 16].ljust(16, b'\x00')
        out += AES.new(key, AES.MODE_CBC, b'\x00' * 16).decrypt(block)
    return out


def _sha256_rounds(key, value, rounds=1000):
    digest = hashlib.sha256()
    digest.update(key)
    for _ in range(rounds):
        digest.update(value)
    return digest.digest()


def _lsa_key(reg, bootkey):
    try:
        pol = reg.open('Policy\\PolEKList').value('').value()
    except Registry.RegistryKeyNotFoundException as exc:
        raise UnsupportedHive(
            'no Policy\\PolEKList (pre-Vista RC4 LSA layout is not supported)') from exc
    return _aes_unwrap(_sha256_rounds(bootkey, pol[28:60]), pol[60:])[68:100]


def _decrypt_secret(lsa_key, record):
    plain = _aes_unwrap(_sha256_rounds(lsa_key, record[28:60]), record[60:])
    length = struct.unpack('<L', plain[:4])[0]
    return plain[16:16 + length]


def get_lsa_secrets(security_path, bootkey):
    """Every LSA secret, decrypted, as ``{name: cleartext_bytes}``.

    Covers ``DPAPI_SYSTEM``, ``$MACHINE.ACC``, ``NL$KM``, ``DefaultPassword``, ``TBAL``
    and any other secret present. Secrets with no current value are skipped.
    """
    secrets = {}
    with open(security_path, 'rb') as handle:
        reg = Registry.Registry(handle)
        lsa_key = _lsa_key(reg, bootkey)
        try:
            root = reg.open('Policy\\Secrets')
        except Registry.RegistryKeyNotFoundException:
            return secrets
        for sub in root.subkeys():
            try:
                record = sub.subkey('CurrVal').value('').value()
            except Registry.RegistryKeyNotFoundException:
                continue
            if not record or len(record) < 60:
                continue
            try:
                secrets[sub.name()] = _decrypt_secret(lsa_key, record)
            except (ValueError, struct.error):
                continue
    return secrets


def get_dpapi_system(security_path, bootkey):
    """The raw ``DPAPI_SYSTEM`` secret (machine key at [4:24], user key at [24:44])."""
    secrets = get_lsa_secrets(security_path, bootkey)
    if 'DPAPI_SYSTEM' not in secrets:
        raise UnsupportedHive('DPAPI_SYSTEM secret not present in this SECURITY hive')
    return secrets['DPAPI_SYSTEM']


def system_master_key_candidates(dpapi_system):
    """The SHA-1 pre-key candidates for SYSTEM master keys, machine key first.

    SYSTEM master keys are protected under the ``DPAPI_SYSTEM`` user key (offset 24)
    in the common case and the machine key (offset 4) in some; both are tried.
    """
    return [dpapi_system[24:44], dpapi_system[4:24]]
